@@ -150,4 +150,60 @@ class ReservationServiceTest {
     void anUnknownReservationIsNotFound() {
         assertEquals(ErrorCode.RESERVATION_NOT_FOUND, errorOf(() -> service.find(42)));
     }
+
+    private Message to(String address) {
+        List<Message> found = sentMessages.all().stream().filter(m -> m.to().equals(address)).toList();
+        assertEquals(1, found.size(), address);
+        return found.get(0);
