+    }
+
+    @Test
+    void cancellingAConfirmedReservationTellsHousekeepingAndFinanceTheRefund() {
+        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
+        service.confirm(reservation.id());
+        service.cancel(reservation.id());
+
+        List<Message> all = sentMessages.all();
+        assertEquals(5, all.size());
+        assertEquals("Reserva cancelada - quarto 201", all.stream()
+                .filter(m -> m.to().startsWith("governanca") && m.subject().startsWith("Reserva cancelada"))
+                .findFirst().orElseThrow().subject());
+        assertTrue(all.stream().anyMatch(m -> m.to().startsWith("financeiro")
+                && m.subject().equals("Reembolso - reserva " + reservation.id())));
+    }
+
+    @Test
+    void noRefundMeansFinanceIsNotTold() {
+        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.NON_REFUNDABLE));
+        service.confirm(reservation.id());
+        service.cancel(reservation.id());
+
+        assertEquals(4, sentMessages.all().size());
+        assertTrue(sentMessages.all().stream().noneMatch(m -> m.subject().startsWith("Reembolso")));
+    }
+
+    @Test
+    void cancellingAPendingReservationTellsNobody() {
+        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
+        service.cancel(reservation.id());
+
+        assertTrue(sentMessages.all().isEmpty());
+    }
 }
